/* radar-score v4 — dashboard theme.
   Dark terminal cockpit: hairline grids, one accent, tabular numerals. No
   framework, no reset library; the page owns every rule below. */

:root {
  --bg: #0a0d12;
  --panel: #10151c;
  --panel-2: #151c26;
  --line: #222c39;
  --text: #e7edf4;
  --dim: #8b9bb0;
  --accent: #38d39f;
  --accent-soft: rgba(56, 211, 159, 0.14);
  --up: #4cc9a2;
  --down: #ef7d6d;
  --warn: #e8b058;
  --info: #5aa8e8;
  --radius: 8px;
  --mono: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, monospace;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

* { box-sizing: border-box; }

html { color-scheme: dark; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-size: 13px;
  line-height: 1.42;
}

#board { max-width: 1340px; margin: 0 auto; padding: 16px 16px 56px; }

.masthead {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 14px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
  flex-wrap: wrap;
}
.masthead-left { display: flex; align-items: center; gap: 9px; }
.glyph {
  width: 22px; height: 22px; border-radius: 6px;
  background: radial-gradient(circle at 30% 30%, var(--accent), #0e5c46 70%);
  box-shadow: 0 0 12px var(--accent-soft);
  display: inline-block;
}
.wordmark { font-size: 16px; letter-spacing: 0.2px; display: block; }
.masthead-left small { color: var(--dim); font-family: var(--mono); font-size: 11px; display: block; max-width: 900px; }
.masthead-meta { display: flex; gap: 12px; color: var(--dim); font-family: var(--mono); font-size: 11px; flex-wrap: wrap; }

/* KPI strip */
.kpis {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 8px;
  padding: 12px 0 4px;
}
.kpi {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 9px 11px;
  min-width: 0;
}
.kpi dt { color: var(--dim); font-size: 10px; text-transform: uppercase; letter-spacing: 0.6px; margin: 0 0 4px; }
.kpi dd { margin: 0; font-size: 17px; font-family: var(--mono); }
.kpi dd small { display: block; color: var(--dim); font-size: 11px; margin-top: 2px; }
.kpi .bar { height: 3px; background: var(--panel-2); border-radius: 2px; margin-top: 6px; overflow: hidden; }
.kpi .bar i { display: block; height: 100%; background: var(--accent); }

/* funnel */
.funnel {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 10px;
  align-items: center;
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
  font-family: var(--mono);
  font-size: 11px;
  color: var(--dim);
}
.funnel b { color: var(--text); font-weight: 600; }
.funnel .chip { padding: 2px 7px; border: 1px solid var(--line); border-radius: 10px; background: var(--panel); }
.funnel .chip.in { color: var(--info); border-color: rgba(90,168,232,0.35); }
.funnel .chip.out { color: var(--down); border-color: rgba(239,125,109,0.35); }
.funnel .chip.net { color: var(--accent); border-color: var(--accent); }

.controls {
  display: flex;
  gap: 10px;
  align-items: flex-end;
  flex-wrap: wrap;
  padding: 12px 0;
  border-bottom: 1px solid var(--line);
}
.field { display: flex; flex-direction: column; gap: 4px; }
.field > span { color: var(--dim); font-size: 10px; text-transform: uppercase; letter-spacing: 0.6px; }
.field input, .field select {
  background: var(--panel);
  color: var(--text);
  border: 1px solid var(--line);
  border-radius: 7px;
