tr.row:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
td.tag { font-family: var(--mono); font-size: 10px; }
.pill { display: inline-block; padding: 2px 7px; border-radius: 10px; border: 1px solid var(--line); font-family: var(--mono); font-size: 10px; }
.pill.keep { color: var(--accent); border-color: var(--accent); background: var(--accent-soft); }
.pill.marginal { color: var(--warn); border-color: var(--warn); }
.pill.pass { color: var(--down); border-color: var(--down); }
