.void { padding: 30px; text-align: center; color: var(--dim); }
.void h2 { margin: 0 0 6px; color: var(--text); }
.void .btn { margin-top: 12px; }

/* coverage + integrity */
.coverage { padding: 14px; background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius); }
.coverage h2 { margin: 0 0 8px; font-size: 14px; }
.coverage h3 { margin: 12px 0 6px; font-size: 11px; color: var(--dim); text-transform: uppercase; letter-spacing: 0.6px; }
.cov-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 6px; }
.cov-row { display: flex; flex-direction: column; gap: 1px; padding: 7px 9px; background: var(--panel-2); border: 1px solid var(--line); border-radius: 7px; }
