.cov-count { font-family: var(--mono); font-size: 15px; color: var(--accent); }
.cov-note { font-size: 10px; color: var(--dim); line-height: 1.3; }
.integrity { display: flex; flex-wrap: wrap; gap: 5px 10px; font-family: var(--mono); font-size: 10px; }
.oos .ok { color: var(--up); font-weight: 600; }
.oos .bad { color: var(--down); font-weight: 600; }
.integrity .ok { color: var(--up); }
