.watch-badge { display: inline-block; margin-top: 3px; font-size: 9px; letter-spacing: 0.06em; text-transform: uppercase; padding: 1px 6px; border-radius: 5px; background: var(--accent-soft); color: var(--accent); border: 1px solid rgba(56, 211, 159, 0.35); }
